const $=s=>document.querySelector(s);let phase=1,index=0,mode='acquisition',referenceMode='ultrasound',done=new Set();try{const a=JSON.parse(localStorage.getItem('fetalview-progress')||'[]');if(Array.isArray(a))done=new Set(a.filter(x=>typeof x==='string'));}catch{}
let sceneAPI=null;const current=()=>phases[phase].lessons[index],key=()=>`${phase}:${current().id}`;
function render(){const p=phases[phase],v=current();$('#trimesters').innerHTML=phases.map((t,i)=>`<button data-phase="${i}" class="${i===phase?'active':''}" aria-pressed="${i===phase}"><strong>${t.title}</strong><span>${t.range}</span></button>`).join('');$('#lessonSelect').innerHTML=p.lessons.map((l,i)=>`<option value="${i}" ${i===index?'selected':''}>${l.group} · ${l.title}</option>`).join('');$('#count').textContent=`${p.lessons.length} VIEWS`;$('#phaseDescription').textContent=p.desc;$('#lessonList').innerHTML=p.lessons.map((l,i)=>`${i===0||l.group!==p.lessons[i-1].group?'<h3 class="lesson-group">'+l.group+'</h3>':''}<button class="lesson ${i===index?'active':''}" data-index="${i}" aria-pressed="${i===index}"><span class="number">${String(i+1).padStart(2,'0')}</span><span><strong>${l.title}</strong><small>${l.en.split(' · ')[0]}</small></span>${done.has(`${phase}:${l.id}`)?'<span class="tick">✓</span>':''}</button>`).join('');const n=p.lessons.filter(l=>done.has(`${phase}:${l.id}`)).length;$('#progressText').textContent=`${n} / ${p.lessons.length}`;$('#progressBar').value=n/p.lessons.length*100;$('#viewTitle').textContent=v.title;$('#viewEnglish').textContent=v.en;$('#lessonIndex').textContent=`${String(index+1).padStart(2,'0')} / ${p.lessons.length}`;$('#planeName').textContent=v.en;$('#modelAge').textContent=`${p.title} 학습 · 공통 외형 모델`;$('#criteria').innerHTML=`<div id="acquisitionPanel" role="tabpanel" aria-labelledby="acquisitionTab">${renderAcquisition(v)}</div><div id="measurementPanel" role="tabpanel" aria-labelledby="measurementTab">${renderMeasurements(v)}</div><div id="anatomyPanel" role="tabpanel" aria-labelledby="anatomyTab">${renderAnatomy(v)}</div><div id="qualityPanel" role="tabpanel" aria-labelledby="criteriaTab"><p class="scope">문서 #${v.documentNumber} · ${v.scope}</p><h3>Best · 최적 영상</h3><p class="quality-text">${v.quality.best}</p><h3>Acceptable · 허용 영상</h3><p class="quality-text">${v.quality.acceptable}</p><div class="tip"><b>해석 메모</b><br>${v.memo}</div>${v.temporal?'<p class="phase-note">신규 HRA 모델에서는 주기별 심실 크기의 교육용 변형을 비교할 수 있습니다. 실제 촬영 주기나 판막 개폐를 재현한 자료는 아니며, 실제 초음파 참고 영상과 해부학 모식도는 각각 정적인 자료입니다. 주기 판정은 실제 cine가 필요합니다.</p>':''}<p class="quality-origin">첨부 문서의 QC 기준입니다. Best/Acceptable은 ISUOG가 모든 단면에 정의한 공식 등급이 아닙니다. 필수 구조 결손·중대한 왜곡으로 판단 또는 측정이 불가능하면 Reject입니다.</p></div>`;$('#quiz').innerHTML=`<p>${v.question}</p>${v.options.map((o,i)=>`<button data-answer="${i}">${String.fromCharCode(65+i)}. ${o}</button>`).join('')}<div class="feedback" role="status" hidden></div>`;$('#complete').textContent=done.has(key())?'학습 완료됨 · 취소하기':'이 단면 학습 완료 ✓';$('#sourceLinks').innerHTML=[phase,3].map(i=>`<a target="_blank" rel="noopener" href="${sources[i][1]}">${sources[i][0]} ↗</a>`).join('');draw(v);renderUltrasound(v,$);setMode(mode);setReference(referenceMode);sceneAPI?.select(v,phase);}
$('#trimesters').onclick=e=>{const b=e.target.closest('[data-phase]');if(b){phase=+b.dataset.phase;index=0;render();}};$('#lessonList').onclick=e=>{const b=e.target.closest('[data-index]');if(b){index=+b.dataset.index;render();}};$('#complete').onclick=()=>{done.has(key())?done.delete(key()):done.add(key());try{localStorage.setItem('fetalview-progress',JSON.stringify([...done]));}catch{}render();};
const guideTabs=['anatomy','acquisition','measurement','criteria','quiz'];
const guidePanels={anatomy:'anatomyPanel',acquisition:'acquisitionPanel',measurement:'measurementPanel',criteria:'qualityPanel',quiz:'quiz'};
function setMode(m){if(!guideTabs.includes(m))return;mode=m;$('#criteria').hidden=m==='quiz';for(const key of guideTabs){const active=key===m,b=$('#'+key+'Tab');b.classList.toggle('selected',active);b.setAttribute('aria-selected',String(active));b.tabIndex=active?0:-1;$('#'+guidePanels[key]).hidden=!active;}}
function tabKeys(event,keys,current,select){let next=keys.indexOf(current);if(event.key==='ArrowRight')next=(next+1)%keys.length;else if(event.key==='ArrowLeft')next=(next+keys.length-1)%keys.length;else if(event.key==='Home')next=0;else if(event.key==='End')next=keys.length-1;else return;event.preventDefault();select(keys[next]);$('#'+keys[next]+'Tab').focus();}
for(const key of guideTabs){$('#'+key+'Tab').onclick=()=>setMode(key);$('#'+key+'Tab').onkeydown=e=>tabKeys(e,guideTabs,mode,setMode);}
function setReference(m){referenceMode=m;for(const key of ['ultrasound','schematic']){const active=key===m,b=$('#'+key+'Tab');b.setAttribute('aria-selected',String(active));b.tabIndex=active?0:-1;b.classList.toggle('selected',active);$('#'+(key==='ultrasound'?'ultrasoundReference':'schematicDetails')).hidden=!active;}}
for(const key of ['ultrasound','schematic']){$('#'+key+'Tab').onclick=()=>setReference(key);$('#'+key+'Tab').onkeydown=e=>tabKeys(e,['ultrasound','schematic'],referenceMode,setReference);}
$('#lessonSelect').onchange=e=>{const next=Number(e.target.value);if(Number.isInteger(next)&&next>=0&&next<phases[phase].lessons.length){index=next;render();}};
$('#quiz').onclick=e=>{const b=e.target.closest('[data-answer]');if(!b)return;const ok=+b.dataset.answer===current().answer;const f=$('#quiz .feedback');f.hidden=false;f.textContent=ok?'정답입니다. 확인 기준을 다시 보고 3D에서 위치를 찾아보세요.':'다시 생각해 보세요. '+current().checks[0];};
$('#allSources').innerHTML=sources.map(s=>`<a href="${s[1]}" target="_blank" rel="noopener">${s[0]} ↗</a>`).join('');$('#sourcesButton').onclick=()=>$('#sources').showModal();$('#closeSources').onclick=()=>$('#sources').close();$('#offset').oninput=e=>{const n=+e.target.value;$('#offsetText').textContent=n===0?'기준 위치':`${n>0?'+':''}${n} · 상대 위치`;sceneAPI?.offset(n);};$('#planeToggle').onchange=e=>sceneAPI?.plane(e.target.checked);$('#skinToggle').onchange=e=>sceneAPI?.skin(e.target.checked);$('#reset').onclick=()=>sceneAPI?.view('reset');$('#front').onclick=()=>sceneAPI?.view('front');$('#side').onclick=()=>sceneAPI?.view('side');
function updateAngles(){const values={};for(const id of ['tilt','rock','rotation']){values[id]=+$('#'+id).value;$('#'+id+'Value').textContent=values[id]+'°';}sceneAPI?.angles(values);}
for(const id of ['tilt','rock','rotation'])$('#'+id).oninput=updateAngles;
$('#planeReset').onclick=()=>{for(const id of ['tilt','rock','rotation']){$('#'+id).value=0;$('#'+id+'Value').textContent='0°';}$('#offset').value=0;$('#offsetText').textContent='프리셋 위치';sceneAPI?.resetPlane();};
$('#focusHeart').onchange=e=>sceneAPI?.focus(e.target.checked);
$('#contextOpacity').oninput=e=>{$('#opacityValue').textContent=e.target.value+'%';sceneAPI?.opacity(+e.target.value);};
$('#organOnly').onchange=()=>sceneAPI?.isolate();$('#organSource').onchange=e=>sceneAPI?.source(e.target.value);$('#cycleEnabled').onchange=e=>sceneAPI?.cycle(e.target.checked);$('#sectionCut').onchange=e=>sceneAPI?.cut(e.target.checked);
function draw(v){const c=$('#diagram'),g=c.getContext('2d');g.clearRect(0,0,600,350);g.fillStyle='#10212b';g.fillRect(0,0,600,350);g.strokeStyle='#25424d';g.lineWidth=1;for(let x=20;x<600;x+=30){g.beginPath();g.moveTo(x,20);g.lineTo(x,330);g.stroke();}for(let y=20;y<350;y+=30){g.beginPath();g.moveTo(20,y);g.lineTo(580,y);g.stroke();}const ellipse=(x,y,rx,ry,col='#b8d2d9',fill='#3a5560')=>{g.beginPath();g.ellipse(x,y,rx,ry,0,0,Math.PI*2);g.fillStyle=fill;g.fill();g.strokeStyle=col;g.lineWidth=3;g.stroke();};const line=(pts,col='#a9c5cf',w=3)=>{g.beginPath();pts.forEach(([x,y],i)=>i?g.lineTo(x,y):g.moveTo(x,y));g.strokeStyle=col;g.lineWidth=w;g.stroke();};const label=()=>{};
const t=v.type;if(drawExtra(v,{g,ellipse,line,label})){}else if(['head','ventricle','cerebellum','earlybrain'].includes(t)){ellipse(300,172,153,120);line([[300,56],[300,284]]);if(v.trimester!==1)ellipse(300,130,15,13);if(t==='head'){ellipse(278,178,18,29);ellipse(322,178,18,29);label('Thalami',418,178);if(v.trimester!==1)label('CSP',321,112);}else if(t==='cerebellum'){ellipse(276,223,27,20);ellipse(324,223,27,20);ellipse(300,258,38,12,'#75dacb','#172e38');label('Cerebellum',391,244);label('CM',315,296);}else{ellipse(258,167,23,54);ellipse(342,167,23,54);label(t==='earlybrain'?'Choroid plexus':'Lateral ventricles',333,315);}label('Falx',304,43);}
else if(t==='abdomen'||t==='kidneys'||t==='pelvis'){ellipse(300,175,147,113);ellipse(300,268,19,12);label('Spine',323,290);if(t==='abdomen'){ellipse(365,155,30,23,'#b8d2d9','#10212b');line([[280,79],[280,158],[315,173]],'#75dacb',9);label('Stomach',392,139);label('Portal sinus',103,48);line([[223,52],[277,136]],'#75dacb',1);}else if(t==='kidneys'){ellipse(249,214,23,37);ellipse(351,214,23,37);label('Kidneys',260,107);}else{ellipse(300,172,35,43,'#75dacb','#142833');label('Bladder',354,166);}}
else if(['heart','lvot','rvot'].includes(t)){ellipse(300,180,149,119);ellipse(300,275,17,12);ellipse(325,170,81,86,'#bbd6df','#243f4b');ellipse(296,133,22,25,'#9fc5d1','#102b38');ellipse(350,134,22,25,'#9fc5d1','#102b38');ellipse(296,198,24,32,'#9fc5d1','#102b38');ellipse(352,198,24,32,'#9fc5d1','#102b38');label('RA',249,125);label('LA',378,125);label('RV',246,218);label('LV',379,218);if(t!=='heart'){line(t==='lvot'?[[352,196],[336,99],[275,65]]:[[296,196],[289,103],[355,70]],'#75dacb',12);label(t==='lvot'?'Aorta':'Pulmonary artery',55,35);}else label('4 CHAMBERS',48,34);}
else if(t==='vessels'){ellipse(300,182,150,117);ellipse(242,160,29,29,'#75dacb');ellipse(318,163,22,22,'#75dacb');ellipse(379,170,15,15);ellipse(365,226,13,13,'#ddbc84','#10212b');label('PA',222,113);label('Ao',300,119);label('SVC',371,132);label('Trachea',385,248);}
else if(t==='femur'){line([[174,244],[410,112]],'#b6d4df',18);[[165,228],[401,96]].forEach(([x,y])=>line([[x-7,y-13],[x+7,y+13]],'#75dacb',2));line([[165,228],[401,96]],'#75dacb',2);label('Ossified diaphysis',204,285);label('FL',244,121);}
else if(t==='face'){ellipse(300,170,105,121);ellipse(262,143,25,19);ellipse(338,143,25,19);line([[300,155],[287,193],[310,193]]);line([[259,218],[281,213],[300,218],[319,213],[341,218]],'#75dacb',4);label('Upper lip',343,247);}
else{ellipse(231,117,67,65);ellipse(321,219,76,45);line([[246,171],[272,207],[318,253],[386,223]],'#b8d2d9',7);line([[273,129],[296,144],[275,157]]);for(let i=0;i<12;i++)ellipse(255+i*10,184+i*5,5,6);if(t==='nt'){line([[259,151],[269,169]],'#75dacb',10);label('NT',304,160);line([[293,158],[274,162]],'#75dacb',1);}else label(t==='spine'?'Spine · longitudinal':'Crown–rump · neutral',180,314);}
finishDiagram(v,{g,ellipse,line},$);g.fillStyle='#9cb4bd';g.font='13px sans-serif';g.fillText('교육용 구조물 그림 · 실제 비율 아님',20,333);}
render();
async function setup3D(){const T=await import('three');const {OrbitControls}=await import('./vendor/OrbitControls.js');const el=$('#viewport');const renderer=new T.WebGLRenderer({antialias:true,alpha:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.localClippingEnabled=true;renderer.toneMapping=T.ACESFilmicToneMapping;renderer.toneMappingExposure=1.1;el.appendChild(renderer.domElement);renderer.domElement.setAttribute('aria-label','회전 가능한 교육용 3D 태아 모델');const scene=new T.Scene();const camera=new T.PerspectiveCamera(38,1,.1,100);camera.position.set(5,2,7);const controls=new OrbitControls(camera,renderer.domElement);controls.target.set(0,.2,0);controls.enableDamping=true;controls.minDistance=4;controls.maxDistance=13;const {attachNavigation}=await import('./navigation.js?v=39');attachNavigation(camera,controls,$);scene.add(new T.HemisphereLight(0xe4f5ff,0x604e47,1.8));const light=new T.DirectionalLight(0xffe6d4,3.2);light.position.set(3,5,5);scene.add(light);const rim=new T.DirectionalLight(0x9ed9df,1.4);rim.position.set(-4,1,-3);scene.add(rim);const fetus=new T.Group();scene.add(fetus);const skins=[];const skin=new T.MeshPhysicalMaterial({color:0xd8ac94,roughness:.52,metalness:0,clearcoat:.18});const organMat=new T.MeshStandardMaterial({color:0xa14659,roughness:.5});const boneMat=new T.MeshStandardMaterial({color:0xe9d9be,roughness:.5});
function ell(pos,size,mat=skin,parent=fetus){const o=new T.Mesh(new T.SphereGeometry(1,40,32),mat);o.position.set(...pos);o.scale.set(...size);parent.add(o);if(mat===skin)skins.push(o);return o;}
function tube(points,r,mat=skin){const curve=new T.CatmullRomCurve3(points.map(p=>new T.Vector3(...p)));const o=new T.Mesh(new T.TubeGeometry(curve,40,r,12,false),mat);fetus.add(o);if(mat===skin)skins.push(o);return o;}
const headGroup=new T.Group();fetus.add(headGroup);const {loadFetalModel}=await import('./fetal-model.js?v=39');$('#modelStatus').textContent='공개 태아 3D 모델을 불러오는 중…';await loadFetalModel(fetus,event=>{if(event.total)$('#modelStatus').textContent='태아 모델 로딩 '+Math.round(event.loaded/event.total*100)+'%';});$('#modelStatus').hidden=true;const grid=new T.GridHelper(7,20,0x315966,0x1e414e);grid.position.y=-1.7;scene.add(grid);const {attachExplorer}=await import('./explorer.js?v=39');const {loadOrganModels}=await import('./organ-models.js?v=39');$('#modelStatus').hidden=false;$('#modelStatus').textContent='공개 해부·태아 MRI 장기 모델을 불러오는 중…';const organAssets=await loadOrganModels();$('#modelStatus').hidden=true;sceneAPI=attachExplorer({scene,camera,controls,fetus,headGroup,ell,organMat,boneMat,grid,$,organAssets});sceneAPI.select(current(),phase);sceneAPI.plane($('#planeToggle').checked);sceneAPI.skin($('#skinToggle').checked);const resize=()=>{renderer.setSize(el.clientWidth,el.clientHeight);camera.aspect=el.clientWidth/el.clientHeight;camera.updateProjectionMatrix();};new ResizeObserver(resize).observe(el);resize();const cranialBase=new T.Vector3(),cranialTip=new T.Vector3();renderer.setAnimationLoop(()=>{controls.update();camera.updateMatrixWorld();cranialBase.copy(controls.target).project(camera);cranialTip.copy(controls.target).add(new T.Vector3(0,.3,0)).project(camera);const dx=(cranialTip.x-cranialBase.x)*el.clientWidth,dy=-(cranialTip.y-cranialBase.y)*el.clientHeight;const arrow=$('#cranialArrow');if(Math.hypot(dx,dy)>4){arrow.textContent='↑';arrow.style.transform=`rotate(${Math.atan2(dx,-dy)}rad)`;$('#cranialLabel').textContent='머리 방향 · 현재 시점 기준';}else{arrow.textContent=camera.position.y>controls.target.y?'⊙':'⊗';arrow.style.transform='none';$('#cranialLabel').textContent=camera.position.y>controls.target.y?'머리 방향 · 화면 바깥쪽':'머리 방향 · 화면 안쪽';}renderer.render(scene,camera);});renderer.domElement.addEventListener('webglcontextlost',e=>{e.preventDefault();$('#error').hidden=false;$('#error').textContent='3D 그래픽 연결이 중단되었습니다. 새로고침하여 다시 시도하세요.';});}
setup3D().catch(()=>{$('#error').hidden=false;$('#modelStatus').hidden=true;$('#error').textContent='태아 3D 모델을 불러오지 못했습니다. 새로고침하고 네트워크 연결 및 브라우저의 WebGL 지원을 확인해 주세요. 단면 학습과 셀프 체크는 계속 사용할 수 있습니다.';});
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'select_fetal_view',description:'임신 분기와 단면 ID를 선택하여 학습 화면을 이동합니다.',inputSchema:{type:'object',properties:{trimester:{type:'integer',minimum:1,maximum:3},viewId:{type:'string'}},required:['trimester','viewId'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||!Number.isInteger(input.trimester)||input.trimester<1||input.trimester>3)throw new Error('Invalid trimester');const p=input.trimester-1;const i=phases[p].lessons.findIndex(x=>x.id===input.viewId);if(i<0)throw new Error('Unknown viewId');phase=p;index=i;render();return {trimester:phase+1,viewId:current().id,title:current().title};}})).catch(()=>{});}catch{}}



